// Builds the envelope for Collect (mail.received). No secret here — the next node (Crypto,
// credential "collect-signing") signs "<t>.<raw>". Field names differ between trigger nodes
// (IMAP / Gmail / Outlook) — adjust the right-hand sides if your node uses others.
return $input.all().map((item) => {
  const m = item.json;
  const headers = m.headers || {};
  const messageId = m.messageId || headers['message-id'] || m.id;
  const refs = (m.references || headers['references'] || '').toString().split(/\s+/).filter(Boolean);
  const envelope = {
    id: messageId,
    type: 'mail.received',
    occurredAt: new Date(m.date || Date.now()).toISOString(),
    data: {
      messageId,
      from: (m.from && (m.from.value ? m.from.value[0].address : m.from)) || '',
      subject: m.subject || '',
      text: m.text || m.textPlain || '',
      html: m.html || m.textHtml || undefined,
      inReplyTo: m.inReplyTo || headers['in-reply-to'] || undefined,
      references: refs,
      attachments: (m.attachments || []).map((a) => ({
        filename: a.filename || a.fileName || 'attachment',
        contentType: a.contentType || a.mimeType || 'application/octet-stream',
        size: a.size || 0,
      })),
    },
  };
  return { json: { raw: JSON.stringify(envelope), t: Math.floor(Date.now() / 1000) } };
});

// Graph → the fields 'Build envelope' expects; remembers the newest receivedDateTime
// (Mail.Read only — messages are never marked read). No secret here.
const data = $getWorkflowStaticData('global');
const items = [];
for (const page of $input.all()) {
  for (const m of page.json.value || []) {
    const h = Object.fromEntries((m.internetMessageHeaders || []).map((x) => [x.name.toLowerCase(), x.value]));
    items.push({ json: {
      messageId: m.internetMessageId || m.id,
      from: (m.from && m.from.emailAddress && m.from.emailAddress.address) || '',
      subject: m.subject || '',
      text: m.body && m.body.contentType === 'text' ? m.body.content : '',
      html: m.body && m.body.contentType === 'html' ? m.body.content : undefined,
      date: m.receivedDateTime,
      inReplyTo: h['in-reply-to'],
      references: h['references'] || '',
      attachments: [],
    } });
    if (!data.since || m.receivedDateTime > data.since) data.since = m.receivedDateTime;
  }
}
return items;
